/* ── Front Desk capture ───────────────────────────────────
 * Landing-page forms post here so submissions land in the
 * admin Front Desk module (not just an email inbox). This is
 * best-effort: if it fails, the form's existing email send
 * still runs, so a lead is never lost.
 * Override the backend origin with VITE_API_URL if needed.
 */
const FRONTDESK_API = (import.meta.env?.VITE_API_URL || 'https://smartious-backend.onrender.com')
  .replace(/\/$/, '') + '/api/frontdesk/submit'

async function captureFrontDesk(payload) {
  try {
    await fetch(FRONTDESK_API, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    })
  } catch (e) {
    // Non-fatal — the email send is the safety net.
    console.error('[front desk capture] failed:', e?.message)
  }
}

/* ── Google Ads conversion tracking ─────────────────────────
 * Fires conversion events for the /us-families paid traffic test.
 * Conversion ID: AW-17733479094 (Smartious Homeschool)
 *
 * Each action below needs a matching Conversion Action created in
 * Google Ads → Tools → Conversions. The "label" string after the slash
 * is unique per action — get it from Google Ads after creating each
 * action and paste it into the table below.
 *
 * Until labels are filled in, events fire to the account ID only and
 * are recorded as generic conversions rather than tied to a specific
 * action. The account-level tracking still works for retargeting.
 */
const GOOGLE_ADS_ID = 'AW-17733479094'
const CONVERSION_LABELS = {
  // Paste the label from Google Ads after creating each conversion action.
  // Format: 'AW-17733479094/abc123XYZ' (the part after the slash is the label)
  consult_booked:  GOOGLE_ADS_ID + '/PASTE_CONSULT_LABEL_HERE',
  enrol_started:   GOOGLE_ADS_ID + '/PASTE_ENROL_LABEL_HERE',
  whatsapp_click:  GOOGLE_ADS_ID + '/PASTE_WHATSAPP_LABEL_HERE',
  phone_click:     GOOGLE_ADS_ID + '/PASTE_PHONE_LABEL_HERE',
}
const CONVERSION_VALUES = {
  consult_booked: 50,
  enrol_started: 200,
  whatsapp_click: 20,
  phone_click: 20,
}
function trackConversion(action) {
  try {
    if (typeof window === 'undefined' || !window.gtag) return
    const sendTo = CONVERSION_LABELS[action]
    const value = CONVERSION_VALUES[action] || 0
    if (!sendTo) return
    window.gtag('event', 'conversion', {
      send_to: sendTo,
      value,
      currency: 'USD',
    })
  } catch (e) {
    console.error('[gtag conversion] failed:', e?.message)
  }
}

/* ── usePageMeta — per-page SEO ────────────────────────────
 * Sets document.title and meta description / OG tags for the
 * current page, so each landing page, curriculum and service
 * page is individually search-friendly. SPA-safe — updates as
 * the user navigates between pages.
 */
function setMetaTag(key, content, attr) {
  if (!content) return
  let el = document.head.querySelector('meta[' + attr + '="' + key + '"]')
  if (!el) {
    el = document.createElement('meta')
    el.setAttribute(attr, key)
    document.head.appendChild(el)
  }
  el.setAttribute('content', content)
}

// setCanonical — writes/updates the <link rel="canonical"> tag.
// One per document. SPA-safe: updates on navigation.
function setCanonical(url) {
  if (!url) return
  let el = document.head.querySelector('link[rel="canonical"]')
  if (!el) {
    el = document.createElement('link')
    el.setAttribute('rel', 'canonical')
    document.head.appendChild(el)
  }
  el.setAttribute('href', url)
}

function usePageMeta(title, description, canonicalOverride) {
  useEffect(() => {
    if (title) document.title = title
    if (description) {
      setMetaTag('description', description, 'name')
      setMetaTag('og:title', title, 'property')
      setMetaTag('og:description', description, 'property')
      setMetaTag('twitter:title', title, 'name')
      setMetaTag('twitter:description', description, 'name')
    }
    // Canonical + og:url — strip query string and trailing slash
    // so URL variants don't fragment SEO authority.
    // Pages can pass a canonicalOverride to force one canonical URL across
    // multiple URL aliases (e.g. /us-families and /online-school/usa both
    // serve the same content but consolidate SEO authority on the latter).
    try {
      const origin = window.location.origin
      let canonical
      if (canonicalOverride) {
        // Allow either absolute URLs or paths starting with '/'
        canonical = canonicalOverride.startsWith('http')
          ? canonicalOverride
          : origin + canonicalOverride
      } else {
        let path = window.location.pathname || '/'
        if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1)
        canonical = origin + path
      }
      setCanonical(canonical)
      setMetaTag('og:url', canonical, 'property')
    } catch {}
  }, [title, description, canonicalOverride])
}

/* ── useHeroPreload — LCP optimization ─────────────────────
 * Hero video on the home page is the LCP element. Inject a
 * <link rel="preload" as="video" fetchpriority="high"> so
 * the browser starts fetching it in parallel with CSS / JS.
 * We pick the mobile-sized Cloudinary encode for narrow
 * viewports and the full-size one elsewhere.
 */
function useHeroPreload(active) {
  useEffect(() => {
    if (!active) return
    const linkId = 'sm-hero-preload'
    if (document.getElementById(linkId)) return
    const link = document.createElement('link')
    link.id = linkId
    link.rel = 'preload'
    link.as = 'video'
    // Hero video is now served from the local public folder (frontend/public/0528.mp4)
    // — same file for mobile and desktop, single MP4 served by Netlify.
    link.href = '/0528.mp4'
    link.setAttribute('type', 'video/mp4')
    link.setAttribute('fetchpriority', 'high')
    document.head.appendChild(link)
    return () => {
      const el = document.getElementById(linkId)
      if (el) el.remove()
    }
  }, [active])
}


