  // Force canonical URL to /online-school/[country] for the families/hub pages
  // so /us-families, /ca-families, /homeschooling-kenya consolidate SEO
  // authority on the canonical /online-school/[country] URL pattern that's
  // been promoted historically.
  let canonicalOverride = null
  if (page === 'us-families') canonicalOverride = '/online-school/usa'
  if (page === 'ca-families') canonicalOverride = '/online-school/canada'
  if (page === 'homeschooling-kenya') canonicalOverride = '/online-school/kenya'
  if (page === 'homeschooling-ethiopia') canonicalOverride = '/online-school/ethiopia'
  if (page === 'homeschooling-rwanda') canonicalOverride = '/online-school/rwanda'
  if (page === 'homeschooling-south-africa') canonicalOverride = '/online-school/south-africa'
  if (page === 'homeschooling-qatar') canonicalOverride = '/online-school/qatar'
  if (page === 'homeschooling-saudi-arabia') canonicalOverride = '/online-school/saudi-arabia'
  if (page === 'homeschooling-uae') canonicalOverride = '/online-school/uae'
  if (page === 'homeschooling-egypt') canonicalOverride = '/online-school/egypt'
  if (page === 'homeschooling-morocco') canonicalOverride = '/online-school/morocco'
  usePageMeta(metaTitle, metaDesc, canonicalOverride)
  useHeroPreload(page === 'home')

  // Load public teacher profiles when the Teachers page is opened.
  // Fetched once, from the public (no-auth) endpoint.
  useEffect(() => {
    if (page !== 'teachers' || teachersLoaded) return
    setTeachersLoading(true)
    const base = (import.meta.env?.VITE_API_URL || 'https://smartious-backend.onrender.com').replace(/\/$/, '')
    fetch(base + '/api/users/public-teachers')
      .then(r => r.json())
      .then(d => { if (d?.success) setPublicTeachers(d.data?.teachers || []) })
      .catch(e => console.error('[teachers] load failed:', e?.message))
      .finally(() => { setTeachersLoading(false); setTeachersLoaded(true) })
  }, [page, teachersLoaded])

  // P(id) — navigate to a landing page by URL. The useEffect
  // above then syncs `page` state. Resets per-page form state.
  const P = (id) => {
    if (!PAGES.includes(id)) return
    setWizStep(1)
    setWizDone(false)
    setPaySuccess('')
    setPayError('')
    setPayProcessing(false)
    setEnrollError('')
    setAssessment([])
    setAssessmentLevel('')
    if (id === 'article') {
      // Article navigation handled by openArticle(); ignore here
      return
    }
    nav(pageToPath(id))
    window.scrollTo(0, 0)
    topRef.current?.scrollIntoView()
  }

  // openArticle(slug) — navigate to an individual blog post URL
